import json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]/"lib/content/courses/authored/diversity-advanced"
def lesson(title, objectives, teaching, case, good, why, bad, badwhy, reflection, action):
    return dict(title=title, objectives=objectives, teaching=teaching, case=case, good=good, why=why, bad=bad, badwhy=badwhy, reflection=reflection, action=action)
def publish(n, slug, title, subtitle, lessons, cards, aid, sources):
    cid=f'div-a{n:02d}-{slug}'
    built=[]
    for i,d in enumerate(lessons,1):
        wc=len(re.findall(r"\b[\w'-]+\b",d['teaching']))
        print(cid,i,wc)
        blocks=[
          {'type':'text','heading':d['title'],'body':''.join('<p>'+p.strip()+'</p>' for p in d['teaching'].strip().split('\n\n'))},
          {'type':'statement','body':'Private reflection: '+d['reflection']},
          {'type':'knowledgeCheck','id':f'{cid}-{i}-check','question':'Which response best applies this lesson to the fictional situation?', 'options':[{'text':d['good'],'correct':True},{'text':d['bad'],'correct':False}], 'feedbackCorrect':d['why'],'feedbackIncorrect':d['badwhy']}]
        blocks.append({'type':'flashcards','heading':'Concepts to carry into practice','cards':[{'front':a,'back':b} for a,b in cards]})
        blocks.append({'type':'leaderMove','heading':'Put the learning to work','control':d['good'],'failure':d['badwhy'],'next':d['action']})
        built.append({'id':f'{cid}-{i}','number':i,'title':d['title'],'summary':d['objectives'][0],'minutes':14,'learning':{'objective':d['objectives'][0],'objectives':d['objectives'],'takeaways':[d['why'],d['badwhy'],d['action']],'evidence':'A fictional case, an explanation of the available responses, private reflection, and an applied next step.','appliedNextStep':d['action']},'scenario':{'context':'Fictional learning case. '+d['case'],'prompt':'What is the most useful next step?','options':[{'label':d['good'],'response':d['why'],'recommended':True},{'label':d['bad'],'response':d['badwhy']}]},'transfer':{'prompt':d['action'],'options':['Use the fictional case to rehearse the action.','Apply the action to an appropriate process within your responsibility, without recording personal learning responses.','Discuss the fictional case with a willing colleague and compare the evidence each response would produce.']},'blocks':blocks})
    pack={'course':{'id':cid,'indexNumber':1320+n,'seriesLabel':'Diversity learning · Advanced','title':title,'subtitle':subtitle,'scope':'For staff, facilitators, supervisors, and leaders in One DHS and One DSD People, Access and Culture. Open to everyone; no prior course or assessment is required. Participation is voluntary. Use fictional examples if you prefer not to reflect on personal experiences. Do not place private reflections or inferred intercultural orientations in employee records. Completion does not count toward DHS-required training credits unless management, a director, or DHS leadership expressly approves an exception.','treatment':'Four substantive lessons with fictional cases, reasoned feedback, concept cards, private reflection, applied practice, a reusable job aid, and source reading.','duration':'About 56 minutes, plus optional practice','author':'One DHS / One DSD — People, Access and Culture','coverImage':'/images/covers/stock-people-10.jpg','coverAlt':'Five colleagues seated around a white conference table in a glass-walled meeting room.','introTranscript':subtitle,'kind':'course','contentType':'practice','governance':{'contentOwner':'One DHS / One DSD People, Access and Culture','reviewers':[],'evidenceDate':'2026-09-22','lastReviewed':'2026-09-22','nextReview':'2027-03-22','updateTriggers':['New evidence or a correction to a source','Changes in the process used for the applied practice'],'relatedDoor':'Learning','toolkitQuestion':'What evidence supports the proposed change, and how will its effects be reviewed?','status':'current'},'learning':{'objectives':[d['objectives'][0] for d in lessons],'evidence':['Explain the reasoning behind a response to each fictional case.','Use the course job aid to propose an observable change and a way to review it.'],'appliedNextStep':lessons[-1]['action']},'lessons':built},'jobAid':{'title':title+' — practice guide','subtitle':'A working aid for examining a decision, preparing a response, and checking what changed.','use':{'purpose':subtitle,'remember':['Keep evidence, interpretation, and proposed action distinct.','Use authorized work records only; keep private learning responses out of personnel records.','A course exercise does not replace formal policy, complaint procedures, professional assessment, or decision authority.'],'doNext':lessons[-1]['action']},'sections':[{'heading':h,'items':items} for h,items in aid]+[{'heading':'Complete a practice record','items':['Decision or situation: describe one concrete example and the specific part within your responsibility.','Evidence: record the observed sequence and identify what is still uncertain; do not include private course reflections or unnecessary personal details.','Proposed action: '+lessons[-1]['action'],'Review: name the person responsible, an appropriate review date, and the evidence that would support continuing, revising, or stopping the change.','Return the result: explain what changed and why to the people who need that information, using an appropriate authorized channel.']}]},'sources':[{'title':t,'href':u,'note':note} for t,u,note in sources]}
    (ROOT/(cid+'.ts')).write_text('import type { CoursePack } from "../../source-types";\n\nconst pack: CoursePack = '+json.dumps(pack,ensure_ascii=False,indent=2).replace('inference','interpretation')+';\n\nexport default pack;\n',encoding='utf-8')



